// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"tr","term":"Blockchain (blok zinciri)","aka":["blok zinciri","blokzincir"],"short":"Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir.","body":[["Bir blockchain'i tek bir bankanın değil, dünyanın dört bir yanındaki binlerce bilgisayarın (",["düğüm","node"],") aynı anda tuttuğu bir muhasebe defteri gibi düşünebilirsiniz. Her blok bir grup işlem içerir ve bir önceki bloğun dijital parmak izini (hash) taşır. Eski bir bloktaki tek bir rakam değişirse parmak izi de değişir, zincir tutmaz ve ağın geri kalanı bu sürümü reddeder."],["Yeni bloğu kimin ekleyeceğine ağın uzlaşma mekanizması karar verir. ",["Bitcoin","bitcoin"]," iş ispatı (",["madencilik","mining"],"), ",["Ethereum","ethereum"]," ise ",["hisse ispatı","proof-of-stake"]," (validatörler) kullanır. Sonuç, herkesin ",["blok gezgini (block explorer)","block-explorer"]," ile inceleyebileceği açık bir işlem geçmişidir."],"Kullanıcı olarak sizin için bunun iki pratik anlamı var: onaylanmış bir işlem fiilen geri alınamaz ve yanlış adrese gönderilen parayı geri çevirecek bir müşteri hizmetleri yoktur. Bu yüzden her çekimden önce ağı ve adresi dikkatle kontrol etmeniz gerekir."],"example":"Bir arkadaşınıza 0,02 BTC gönderdiğinizi varsayalım. İşleminiz önce bekleme alanında sıraya girer, sonra bir madenci onu bir bloğa ekler. Bitcoin'de ortalama her 10 dakikada bir blok üretilir; birçok borsa 3 ile 6 onay arasında bir eşik kullanır, yani 6 onay için yaklaşık 60 dakika beklersiniz. Biri ödemenizin bulunduğu bloğu silmek isterse, o bloğu ve sonrasında gelen her bloğu tüm dürüst ağdan daha hızlı yeniden üretmesi gerekir; büyük bir ağda bu son derece pahalıdır.","mistakes":["Coinlerin borsa uygulamasının içinde durduğunu sanmak; blockchain aslında adreslere bağlı bakiyeleri kaydeder.","Onaylanmış bir transferin destek ekibine yazarak iptal edilebileceğini düşünmek.","Tüm blockchain'leri aynı sanıp, alıcı adresin desteklemediği bir ağ üzerinden para göndermek."],"faq":[{"q":"Blockchain ne işe yarar?","a":"Kimsenin tek başına değiştiremeyeceği bir işlem ve veri kaydı tutmaya yarar. En bilinen kullanımı kripto paralardır, ancak tedarik zinciri takibi gibi alanlarda da kullanılır."},{"q":"Blockchain ile Bitcoin aynı şey mi?","a":"Hayır. Bitcoin, blockchain teknolojisini kullanan ilk kripto paradır. Ethereum, Solana ve diğer ağların her biri kendi blockchain'ine sahiptir."},{"q":"Blockchain hacklenebilir mi?","a":"Büyük ağların geçmiş kayıtlarını değiştirmek pratikte çok zordur. Saldırıların çoğu zincirin kendisini değil; cüzdanları, borsaları veya akıllı kontrat hatalarını hedef alır."}],"title":"Blockchain nedir? Blok zinciri nasıl çalışır?","description":"Blockchain'in ne olduğunu, blokların nasıl birbirine bağlandığını ve onaylı işlemlerin neden geri alınamadığını öğrenin.","related":[["cryptocurrency","Kripto para (cryptocurrency)","Kripto para, bir merkez bankası ya da şirket yerine bir blockchain ağı tarafından kaydı tutulan, kriptografiyle korunan ve internet üzerinden doğrudan kişiden kişiye gönderilebilen dijital bir varlıktır."],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["block-explorer","Blok gezgini (block explorer)","Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"tr","term":"İşlem hacmi (Trading volume)","aka":["hacim","24 saatlik hacim","volume"],"short":"İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır.","body":[["Hacim coin adedi ya da ",["USDT","usdt"]," veya dolar karşılığı olarak gösterilir. Bir borsadaki tek bir paritenin hacmi yalnızca o piyasayı yansıtır; veri siteleri ise birçok borsanın hacmini toplayarak genel bir rakam verir. Grafiklerde hacim genellikle mumların altında çubuklar olarak görünür."],["Yatırımcılar hacmi bir fiyat hareketinin ne kadar güçlü olduğunu anlamak için kullanır. Yüksek hacimle gelen bir yükseliş çok sayıda katılımcının işin içinde olduğunu gösterir; düşük hacimli bir hareket daha kolay tersine dönebilir. Hacim aynı zamanda ",["likidite","liquidity"]," hakkında da fikir verir."],["Spot hacim ile vadeli işlem hacmini ayrı değerlendirin; vadeli piyasalarda ",["kaldıraç","leverage"]," nedeniyle hacim çoğu zaman çok daha yüksektir. Bazı küçük borsalarda hacim, ",["wash trading","wash-trading"]," denilen sahte işlemlerle şişirilebilir. Bu yüzden tek bir rakama körü körüne güvenmeyin."]],"example":["Bir coinin 24 saatlik hacmi 50 milyon USDT, ",["piyasa değeri","market-capitalization"]," 500 milyon USDT olsun. Bu, bir günde piyasa değerinin yaklaşık yüzde 10'u kadar işlem yapıldığı anlamına gelir. Ertesi gün fiyat yüzde 8 yükselirken hacim 150 milyon USDT'ye çıkarsa, hareketin arkasında normalin üç katı katılım vardır. Fiyat aynı oranda yükselip hacim 20 milyon USDT'ye düşseydi, hareketin çok daha zayıf bir katılımla gerçekleştiğini düşünürdünüz."],"mistakes":["Hacmi piyasa değeriyle karıştırmak; hacim işlem miktarını, piyasa değeri ise dolaşımdaki arzın toplam değerini gösterir.","Spot ve vadeli hacmi toplayıp tek bir rakam gibi yorumlamak.","Az bilinen bir borsadaki çok yüksek hacmi gerçek talep sanmak."],"faq":[{"q":"Yüksek işlem hacmi iyi bir şey mi?","a":"Yüksek hacim genellikle daha iyi likidite ve daha dar makas anlamına gelir. Ancak tek başına fiyatın yönü hakkında bir şey söylemez ve sahte hacim ihtimali her zaman kontrol edilmelidir."},{"q":"24 saatlik hacim nasıl hesaplanır?","a":"Son 24 saatte gerçekleşen tüm işlemlerin miktarı toplanır. Kayan bir zaman penceresi kullanıldığı için rakam sürekli güncellenir."}],"title":"İşlem hacmi nedir? Kriptoda hacim nasıl okunur","description":"İşlem hacminin ne olduğunu, fiyat hareketini nasıl doğruladığını ve sahte hacmi nasıl ayırt edeceğinizi öğrenin.","related":[["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."],["open-interest","Açık pozisyon miktarı (Open interest)","Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir."],["wash-trading","Wash trading (Sahte işlem)","Wash trading, aynı kişinin veya iş birliği yapan tarafların kendi kendine alıp satarak gerçek bir talep yokken yapay işlem hacmi ve fiyat hareketi yaratmasıdır."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"tr","term":"Pozisyon büyüklüğü (Position sizing)","aka":["pozisyon boyutu","işlem büyüklüğü","position size"],"short":"Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir.","body":[["Önce tek bir işlemde hesabınızın ne kadarını kaybetmeye razı olduğunuza karar verirsiniz; birçok işlemci bunu yüzde 1 ile 2 arasında tutar. Sonra giriş fiyatı ile zarar durdur (",["stop-loss","stop-loss"],") arasındaki mesafeyi ölçersiniz. Pozisyon büyüklüğü, kabul edilen kaybın bu mesafeye bölünmesiyle bulunur."],["Bu hesap kaldıraçtan bağımsızdır. ",["Kaldıraç","leverage"]," yalnızca ne kadar teminat bağlayacağınızı değiştirir; doğru pozisyon büyüklüğü ise stop'a takıldığınızda kaybın planladığınız tutarda kalmasını sağlar. Stop uzaktaysa pozisyon küçülmeli, yakınsa büyüyebilir."],["Kaldıraçlı işlemlerde ",["likidasyon (tasfiye)","liquidation"]," fiyatının stop seviyenizden önce gelmediğini mutlaka kontrol edin. İşlem ücretleri ve ",["kayma","slippage"]," da gerçek kaybı hesapladığınızdan biraz büyütebilir."]],"example":["Hesabınızda 5.000 ",["USDT","usdt"]," var ve işlem başına en fazla yüzde 1, yani 50 USDT kaybetmek istiyorsunuz. SOL'u 150 USDT'den alacak, stop'u 144 USDT'ye koyacaksınız; aradaki mesafe 6 USDT. Pozisyon büyüklüğü 50 / 6 = yaklaşık 8,3 SOL, yani yaklaşık 1.250 USDT değerindedir. Bu pozisyonu 5x kaldıraçla açarsanız yalnızca 250 USDT teminat bağlarsınız, ama stop'a takıldığınızda kaybınız yine yaklaşık 50 USDT olur."],"mistakes":["Pozisyon büyüklüğünü stop mesafesine göre değil, hislere göre seçmek.","Yüksek kaldıracı pozisyonu büyütmek için kullanıp tek işlemde hesabın büyük kısmını riske atmak.","Ücret ve kaymayı hesaba katmadan riskin tam olarak planlanan tutarda kalacağını sanmak."],"faq":[{"q":"Pozisyon büyüklüğü nasıl hesaplanır?","a":"Kabul ettiğiniz kayıp tutarını giriş fiyatı ile stop fiyatı arasındaki farka bölersiniz. Sonuç, alacağınız coin miktarıdır."},{"q":"Yüzde 1 kuralı nedir?","a":"Tek bir işlemde hesabın en fazla yüzde 1'ini kaybetmeyi hedefleyen yaygın bir risk kuralıdır. Böylece arka arkaya gelen birkaç kayıp hesabı ciddi şekilde eritmez."}],"title":"Pozisyon büyüklüğü nedir? Kriptoda nasıl hesaplanır","description":"İşlem başına riskinizi sabitlemek için pozisyon büyüklüğünü stop mesafesine göre nasıl hesaplayacağınızı öğrenin.","related":[["risk-reward-ratio","Risk-ödül oranı (Risk-reward ratio)","Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Ne kadar alacağınıza karar vermeden önce ne kadar kaybedebileceğinizi belirleyin"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"tr","term":"Fonlama oranı (Funding rate)","aka":["funding rate","fonlama ücreti","funding fee"],"short":"Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır.","body":[["Oran pozitifse ",["long pozisyon","long-and-short"]," sahipleri short tarafına öder; bu genellikle kontrat fiyatının spotun üzerinde olduğu, piyasada long talebinin baskın olduğu dönemlerde görülür. Oran negatifse short tarafı long tarafına öder. Ödeme borsaya değil, iki taraf arasında yapılır."],"Ödeme, pozisyonunuzun nominal değeri ile oranın çarpımıdır; teminat tutarınıza göre değil. Bu yüzden yüksek kaldıraçla açılan bir pozisyonda fonlama, teminata göre çok büyük bir maliyete dönüşebilir. Yalnızca ödeme anında açık olan pozisyonlar fonlama öder veya alır.","Fonlama çoğu borsada 8 saatte bir yapılır, ancak bazı borsa ve paritelerde 1, 2 veya 4 saatlik aralıklar kullanılır ve oranın üst-alt sınırları farklıdır. Kullandığınız kontratın şartname sayfasından aralığı ve bir sonraki ödeme saatini kontrol edin."],"example":[["BTC","bitcoin"]," ",["perpetual","perpetual-futures"]," kontratında 0,5 BTC long pozisyonunuz var ve işaret fiyatı 64.000 ",["USDT","usdt"],"; nominal değer 32.000 USDT. Fonlama oranı yüzde 0,03 ise ödeme anında 32.000 × 0,0003 = 9,6 USDT ödersiniz. Bu pozisyonu 8x kaldıraçla 4.000 USDT teminatla açtıysanız, oran günde üç kez aynı kalırsa günlük maliyet 28,8 USDT, yani teminatınızın yaklaşık yüzde 0,72'si olur."],"mistakes":["Fonlamayı teminat üzerinden hesaplayıp maliyeti olduğundan küçük sanmak.","Ödeme saatinden hemen önce pozisyon açıp beklenmedik bir fonlama ödemek.","Yüksek pozitif fonlamayı tek başına fiyatın düşeceğinin kesin işareti saymak."],"faq":[{"q":"Negatif fonlama oranı ne demek?","a":"Short pozisyon sahiplerinin long tarafına ödeme yaptığı anlamına gelir. Genellikle kontrat fiyatı spotun altındadır ve piyasada short talebi baskındır, ancak bu tek başına yön tahmini için yeterli değildir."},{"q":"Fonlama ücretini borsa mı alır?","a":"Hayır. Fonlama long ve short pozisyon sahipleri arasında el değiştirir. Borsa yalnızca işlem ücretlerini tahsil eder."},{"q":"Fonlama ne sıklıkla ödenir?","a":"Çoğu kontratta 8 saatte bir, bazılarında 1, 2 veya 4 saatte bir ödenir. Kesin aralık borsaya ve pariteye göre değişir."}],"title":"Fonlama oranı (funding rate) nedir? Nasıl hesaplanır","description":"Perpetual kontratlarda fonlama oranının nasıl işlediğini, kimin kime ödediğini ve maliyetin nasıl hesaplandığını öğrenin.","related":[["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["funding-rate-arbitrage","Fonlama oranı arbitrajı (Funding rate arbitrage)","Fonlama oranı arbitrajı, spot piyasada bir coin alıp aynı miktarda perpetual short açarak fiyat riskini nötrlediğiniz ve pozitif fonlama ödemelerini topladığınız stratejidir."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır."],["open-interest","Açık pozisyon miktarı (Open interest)","Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Fiyat sabit, bakiye düştü mü? Maliyetleri unutmadan son aşamayı tamamlayın"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"tr","term":"DeFi (merkeziyetsiz finans)","aka":["merkeziyetsiz finans","decentralized finance","DeFi"],"short":"DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir.","body":[["DeFi'de bir işlemi yapan şey bir şirket çalışanı değil, herkesin kodunu görebildiği akıllı sözleşmelerdir. Uniswap gibi merkeziyetsiz borsalar token takası, Aave gibi protokoller borç verme ve alma, Lido gibi platformlar ",["likit staking","liquid-staking"]," sunar. Bu uygulamalara saklama dışı bir cüzdanla bağlanırsınız; hesap açma veya ",["kimlik doğrulama","kyc"]," genellikle gerekmez."],"Avantajları açıklık ve birleştirilebilirliktir: bir protokolde aldığınız token'ı başka bir protokolde teminat olarak kullanabilirsiniz. İşlemler şeffaf biçimde blokzincirde kayıtlıdır ve aracı kurum kapandığında fonlar kilitlenmez.",["Riskleri de farklıdır. ",["Akıllı sözleşme","smart-contract"]," hataları, oracle manipülasyonu, ",["rug pull","rug-pull"],", yanlış token onayları ve yüksek ağ ücretleri kayıplara yol açabilir. Hata yaptığınızda başvuracağınız bir müşteri hizmetleri yoktur. Düzenleyici çerçeve de ülkeden ülkeye değişir ve hâlâ gelişmektedir."]],"example":["Elinizde 1.000 ",["USDC","usdc"]," olduğunu varsayalım. Bir ",["DeFi borç verme","defi-lending"]," protokolüne yatırdığınızda, protokol bu USDC'yi borç alanlara verir ve faiz oranı arz-talebe göre değişir. Yıllık oran o dönem yüzde 5 civarında seyrederse bir yılda yaklaşık 50 USDC faiz birikir. Bu sırada ağ ücreti olarak örneğin 3 USDC ödersiniz. Ancak protokolde bir güvenlik açığı istismar edilirse yatırdığınız 1.000 USDC'nin bir kısmı veya tamamı risk altına girebilir."],"mistakes":["DeFi getirilerinin bankadaki mevduat gibi sabit ve garantili olduğunu sanmak.","Denetim geçmişine ve protokolün ne kadar süredir çalıştığına bakmamak.","Ağ ücretlerini hesaba katmadan küçük tutarlarla sık işlem yapmak."],"faq":[{"q":"DeFi ile CeFi arasındaki fark nedir?","a":"CeFi'de bir şirket (borsa gibi) varlıklarınızı saklar ve işlemleri yönetir. DeFi'de işlemler akıllı sözleşmelerle yürür ve varlıklar sizin cüzdanınızda veya protokol sözleşmesinde durur."},{"q":"DeFi kullanmak için ne gerekir?","a":"Saklama dışı bir cüzdan, ilgili ağın ağ ücreti için yerel token'ı (Ethereum'da ETH gibi) ve kullanacağınız varlık yeterlidir."}],"title":"DeFi nedir? Merkeziyetsiz finans nasıl çalışır?","description":"DeFi'nin ne olduğunu, akıllı sözleşmelerle nasıl çalıştığını, sunduğu fırsatları ve taşıdığı riskleri öğrenin.","related":[["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["total-value-locked","Kilitli toplam değer (TVL)","Kilitli toplam değer (TVL), bir DeFi protokolünün veya blokzincirin akıllı sözleşmelerinde yatırılmış olarak duran tüm varlıkların güncel piyasa değeridir."],["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir."],["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"tr","term":"Zincirler arası köprü (cross-chain bridge)","aka":["köprü","bridge","cross-chain bridge","blokzincir köprüsü"],"short":"Zincirler arası köprü, bir kripto varlığı bir blokzincirden diğerine taşımanızı sağlayan ve genellikle varlığı kaynak zincirde kilitleyip hedef zincirde bir karşılığını çıkararak çalışan protokoldür.","body":[["Blokzincirler birbirinin verisini doğrudan okuyamaz. Köprüler bu boşluğu doldurur. En yaygın model kilitle ve bas (lock and mint) modelidir: ",["Ethereum","ethereum"],"'daki ",["USDC","usdc"],"'nizi köprü sözleşmesine kilitlersiniz, hedef ağda aynı miktarda temsil token'ı basılır. Geri dönüşte hedefteki token yakılır, kaynaktaki varlık serbest bırakılır."],["Arbitrum ve Optimism gibi ",["katman 2","layer-2"]," ağların kendi resmî köprüleri vardır; bunların yanında birçok ağı birbirine bağlayan üçüncü taraf köprüler de bulunur. Circle'ın CCTP'si gibi bazı sistemler ise token'ı kaynakta yakıp hedefte yerel olarak yeniden basar."],"Köprüler kriptoda büyük saldırıların sık yaşandığı alanlardan biridir, çünkü sözleşmelerinde yüksek miktarda varlık birikir. Bir köprü hacklenirse hedef zincirdeki temsil token'ları karşılıksız kalabilir. Ayrıca bazı resmî katman 2 köprülerinde geri çekim günler sürebilir. Bu yüzden köprünün güvenlik modelini ve bekleme sürelerini bilmek önemlidir."],"example":["Ethereum'daki 1.000 USDC'yi Arbitrum'a taşımak istiyorsunuz. Köprüde Ethereum ",["ağ ücreti","gas-fee"]," örneğin 4 USDC, köprü ücreti 1 USDC tutuyor; Arbitrum'a yaklaşık 995 USDC ulaşıyor. Alternatif olarak, borsanızda Arbitrum çekimi destekleniyorsa USDC'yi doğrudan Arbitrum ağından çekmek daha ucuz olabilir. İşlemden önce hedef ağda ağ ücreti için az miktarda ETH bulunduğundan da emin olmalısınız."],"mistakes":["Sahte köprü sitelerine arama reklamlarından girmek.","Hedef ağda ağ ücreti için yerel token bulundurmamak.","Köprülenmiş token ile yerel olarak çıkarılmış token'ı aynı şey sanmak."],"faq":[{"q":"Köprü kullanmak güvenli mi?","a":"Güvenlik köprünün tasarımına ve geçmişine bağlıdır. Resmî ve uzun süredir çalışan köprüler genellikle daha az risklidir, ancak hiçbiri risksiz değildir."},{"q":"Köprü yerine borsa kullanabilir miyim?","a":"Evet. Varlığı borsaya bir ağdan yatırıp başka bir ağdan çekmek çoğu zaman pratik bir alternatiftir; borsanın her iki ağı da desteklediğini kontrol edin."}],"title":"Kripto köprü (bridge) nedir? Zincirler arası transfer","description":"Zincirler arası köprülerin nasıl çalıştığını, kilitle ve bas modelini, ücretleri ve köprü risklerini öğrenin.","related":[["wrapped-token","Sarılmış token (wrapped token)","Sarılmış token, başka bir varlığı birebir temsil eden ve onu farklı bir blokzincirde veya farklı bir token standardında kullanılabilir hâle getiren token'dır; örneğin WBTC, Ethereum'da Bitcoin'i temsil eder."],["layer-2","Katman 2 (Layer 2, L2)","Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır."],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"tr","term":"Stablecoin (sabit coin)","aka":["stablecoin","sabit coin","stabil coin","sabit para"],"short":"Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır.","body":[["En yaygın tür, nakit ve kısa vadeli devlet tahvili gibi rezervlerle desteklenen itibari para destekli stablecoin'lerdir: Tether'ın çıkardığı ",["USDT","usdt"]," ve Circle'ın çıkardığı ",["USDC","usdc"]," buna örnektir. ",["Kripto teminatlı stablecoin","crypto-backed-stablecoin"],"'ler (DAI gibi) aşırı teminatla, sentetik dolarlar ise türev pozisyonlarıyla sabitliği korumaya çalışır."],["Stablecoin'ler kripto alım satımında ana işlem birimidir. Birçok borsa çiftlerini USDT veya USDC karşısında listeler. Ayrıca hızlı transferler, ",["DeFi","defi"]," işlemleri ve bazı ülkelerde değer saklama amacıyla kullanılır. Türkiye'de de USDT, kripto kullanıcıları arasında yaygın biçimde kullanılan bir stablecoin'dir."],["Sabitlik garanti değildir. Rezervlerin kalitesi, ihraççının güvenilirliği, düzenleyici kararlar ve piyasa paniği bir stablecoin'in 1 dolardan sapmasına (",["depeg","depeg"],") yol açabilir. AB'de ",["MiCA","mica"]," kuralları stablecoin ihraççıları için 30 Haziran 2024'ten itibaren uygulanmaktadır; diğer ülkelerde kurallar farklıdır."]],"example":"TL birikiminizin bir kısmını USDT'ye çevirdiğinizi varsayalım: 1 USDT o gün 34 TL ve 34.000 TL ile 1.000 USDT alıyorsunuz. Altı ay sonra dolar kuru 38 TL'ye çıkarsa 1.000 USDT'niz yaklaşık 38.000 TL eder. Ancak USDT'nin dolar sabitliği kısa süreliğine 0,99'a inerse, aynı anda 1.000 USDT'nin değeri yaklaşık 990 dolar olur. Örnekteki kurlar sadece hesap içindir, güncel piyasa verisi değildir.","mistakes":["Tüm stablecoin'lerin aynı rezerv yapısına ve riske sahip olduğunu sanmak.","Stablecoin'i bir banka mevduatı gibi devlet güvencesi altında sanmak.","Transfer sırasında stablecoin'in hangi ağda gönderildiğini kontrol etmemek."],"faq":[{"q":"Stablecoin'ler gerçekten 1 dolar mı?","a":"Amaç 1 dolara yakın kalmaktır ve çoğu zaman bu sağlanır. Ancak piyasa stresinde kısa süreli veya kalıcı sapmalar yaşanabilir."},{"q":"En güvenli stablecoin hangisi?","a":"Tek bir cevap yoktur. Rezerv şeffaflığı, ihraççının düzenleyici durumu, likidite ve kullandığınız ağ birlikte değerlendirilmelidir."}],"title":"Stablecoin nedir? Sabit coin türleri ve riskleri","description":"Stablecoin'lerin nasıl sabit kaldığını, itibari para destekli ve kripto teminatlı türlerini ve depeg riskini öğrenin.","related":[["usdt","USDT (Tether)","USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir."],["usdc","USDC (USD Coin)","USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."],["crypto-backed-stablecoin","Kripto teminatlı stablecoin","Kripto teminatlı stablecoin, dolar rezervi yerine akıllı sözleşmede kilitlenen ETH gibi kripto varlıklarla, genellikle değerinden fazla teminatla desteklenen stablecoin'dir."],["synthetic-dollar","Sentetik dolar (delta nötr stablecoin)","Sentetik dolar, spot kripto varlığı tutup aynı büyüklükte short vadeli pozisyon açarak fiyat riskini sıfırlayan ve böylece yaklaşık 1 dolar değerinde kalmayı hedefleyen token'dır."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
